--
-- Table structure for table `dimwaktu`
--

CREATE TABLE `dimwaktu` (
  `WaktuID` int NOT NULL,
  `Tanggal` date NOT NULL,
  `Hari` int DEFAULT NULL,
  `Bulan` int DEFAULT NULL,
  `Tahun` int DEFAULT NULL,
  `NamaHari` varchar(20) DEFAULT NULL,
  `NamaBulan` varchar(20) DEFAULT NULL,
  `Kuartal` int DEFAULT NULL,
  `Semester` int DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

